package org.eclipse.kura.openapi;

import static org.mockito.Mockito.when;

import org.junit.Test;

public class SystemHttpContractTest extends AbstractHttpContractTest {

    @Test
    public void allPropertyReadsMatchTheContract() throws Exception {
        givenServer();

        whenRequest("GET", "/system/v1/properties/framework", null);

        whenRequest("GET", "/system/v1/properties/extended", null);

        whenRequest("GET", "/system/v1/properties/kura", null);

        thenLastResponsesMatchContract(200, 200, 200);
    }

    @Test
    public void allFilteredReadsMatchTheContract() throws Exception {
        givenServer();

        whenRequest("POST", "/system/v1/properties/framework/filter", "{\"names\":[\"deviceName\"]}");

        whenRequest("POST", "/system/v1/properties/extended/filter", "{\"groupNames\":[]}");

        whenRequest("POST", "/system/v1/properties/kura/filter", "{\"names\":[\"test.property\"]}");

        thenLastResponsesMatchContract(200, 200, 200);
    }

    @Test
    public void malformedJsonMatchesTheErrorContract() throws Exception {
        givenServer();

        whenRequest("POST", "/system/v1/properties/framework/filter", "{");

        thenResponseMatchesContract(400);
    }

    @Test
    public void serviceFailureMatchesTheErrorContract() throws Exception {
        givenServer();
        givenFailingSystemService();

        whenRequest("GET", "/system/v1/properties/framework", null);

        thenResponseMatchesContract(500);
    }

    private void givenFailingSystemService() {
        when(this.system.getDeviceName()).thenThrow(new IllegalStateException("Unavailable"));
    }
}
